CREATE TABLE IF NOT EXISTS projetos (id BIGSERIAL PRIMARY KEY, titulo VARCHAR(160) NOT NULL, categoria VARCHAR(80) NOT NULL, descricao TEXT NOT NULL, tags TEXT NOT NULL DEFAULT '', link VARCHAR(500), imagem VARCHAR(500), destaque BOOLEAN NOT NULL DEFAULT FALSE, criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS servicos (id BIGSERIAL PRIMARY KEY, titulo VARCHAR(160) NOT NULL, descricao TEXT NOT NULL, icone VARCHAR(80));
CREATE TABLE IF NOT EXISTS mensagens_contato (id BIGSERIAL PRIMARY KEY, nome VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL, empresa VARCHAR(160), projeto VARCHAR(160), mensagem TEXT, data_envio TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS usuarios_admin (id BIGSERIAL PRIMARY KEY, nome VARCHAR(120) NOT NULL, email VARCHAR(254) UNIQUE NOT NULL, senha_hash VARCHAR(255) NOT NULL, ativo BOOLEAN NOT NULL DEFAULT TRUE, criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS habilidades (id BIGSERIAL PRIMARY KEY, categoria VARCHAR(120) NOT NULL, nome VARCHAR(120) NOT NULL, nivel INTEGER NOT NULL DEFAULT 1 CHECK (nivel BETWEEN 1 AND 5), ordem INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS qualificacoes (id BIGSERIAL PRIMARY KEY, titulo VARCHAR(200) NOT NULL, instituicao VARCHAR(200) NOT NULL, tipo VARCHAR(80) NOT NULL, data_inicio DATE, data_fim DATE, descricao TEXT, documento_url VARCHAR(500));
CREATE TABLE IF NOT EXISTS carreiras (id BIGSERIAL PRIMARY KEY, cargo VARCHAR(160) NOT NULL, empresa VARCHAR(160) NOT NULL, periodo VARCHAR(120) NOT NULL, tipo VARCHAR(80), descricao TEXT, conquistas TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_projetos_destaque ON projetos (destaque);
CREATE INDEX IF NOT EXISTS idx_mensagens_data_envio ON mensagens_contato (data_envio DESC);
CREATE INDEX IF NOT EXISTS idx_habilidades_categoria ON habilidades (categoria);
